Script.Workflow:
module Win10Palette;
using presentation::*;
namespace win10skin
{
  struct StateColors
  {
    Border : Color;
    Fill : Color;
    Text : Color;
    HideBackground : bool;
  }

  struct ColorPackage
  {
    Page : Color;
    Chrome : Color;
    Divider : Color;
    Outline : Color;
    StrongOutline : Color;
    Text : Color;
    SecondaryText : Color;
    DisabledText : Color;
    Accent : Color;
    OnAccent : Color;
    Link : Color;
    ScrollThumb : Color;
    ScrollThumbHovered : Color;
    ScrollThumbPressed : Color;
    WindowEdge : Color;
    WindowEdgeInactive : Color;
    CloseHovered : Color;
    ClosePressed : Color;
    ButtonNormal : StateColors;
    ButtonHovered : StateColors;
    ButtonPressed : StateColors;
    ButtonDisabled : StateColors;
    InputNormal : StateColors;
    InputHovered : StateColors;
    InputFocused : StateColors;
    InputDisabled : StateColors;
    CommandNormal : StateColors;
    CommandHovered : StateColors;
    CommandPressed : StateColors;
    CommandDisabled : StateColors;
    ItemNormal : StateColors;
    ItemHovered : StateColors;
    ItemSelected : StateColors;
    ItemSelectedHovered : StateColors;
    ItemDisabled : StateColors;
    WindowSurface : Color;
    MenuHighlight : Color;
    RibbonSurface : Color;
    RibbonBorder : Color;
    RibbonHovered : StateColors;
    RibbonSelected : StateColors;
    RibbonPressed : StateColors;
    TabNormal : StateColors;
    TabHovered : StateColors;
  }

  func CreateColorPackageInternal(dark : bool) : ColorPackage
  {
    var page = dark ? cast Color "#202020" : cast Color "#FFFFFF";
    var chrome = dark ? cast Color "#2B2B2B" : cast Color "#F2F2F2";
    var divider = dark ? cast Color "#484848" : cast Color "#D9D9D9";
    var outline = dark ? cast Color "#797979" : cast Color "#7A7A7A";
    var strongOutline = dark ? cast Color "#CCCCCC" : cast Color "#333333";
    var text = dark ? cast Color "#FFFFFF" : cast Color "#000000";
    var secondaryText = dark ? cast Color "#C2C2C2" : cast Color "#5C5C5C";
    var disabledText = dark ? cast Color "#858585" : cast Color "#7A7A7A";
    var accent = cast Color "#0078D7";
    var onAccent = cast Color "#FFFFFF";
    var link = dark ? cast Color "#60CDFF" : cast Color "#0063B1";
    var scrollThumb = dark ? cast Color "#737373" : cast Color "#A6A6A6";
    var scrollThumbHovered = dark ? cast Color "#A6A6A6" : cast Color "#767676";
    var scrollThumbPressed = dark ? cast Color "#C2C2C2" : cast Color "#606060";
    var windowEdge = cast Color "#707070";
    var windowEdgeInactive = dark ? cast Color "#3A3A3A" : cast Color "#CCCCCC";
    var closeHovered = cast Color "#E81123";
    var closePressed = dark ? cast Color "#A00B18" : cast Color "#C50F1F";
    var windowSurface = dark ? cast Color "#191919" : cast Color "#F0F0F0";
    var button = dark ? cast Color "#333333" : cast Color "#E1E1E1";
    var buttonEdge = dark ? cast Color "#9B9B9B" : cast Color "#ADADAD";
    var buttonHot = dark ? cast Color "#454545" : cast Color "#E5F1FB";
    var buttonDown = dark ? cast Color "#666666" : cast Color "#CCE4F7";
    var disabledEdge = dark ? cast Color "#404040" : cast Color "#BFBFBF";
    var disabledFace = dark ? button : cast Color "#CCCCCC";
    var commandHot = dark ? cast Color "#383838" : cast Color "#E5F3FF";
    var commandDown = dark ? cast Color "#494949" : cast Color "#CCE8FF";
    var menuHighlight = dark ? cast Color "#414141" : cast Color "#99D1FF";
    var selected = dark ? cast Color "#767676" : cast Color "#CCE8FF";
    var selectedHover = dark ? cast Color "#767676" : cast Color "#B2DBFF";
    return {
      Page: page;
      Chrome: chrome;
      Divider: divider;
      Outline: outline;
      StrongOutline: strongOutline;
      Text: text;
      SecondaryText: secondaryText;
      DisabledText: disabledText;
      Accent: accent;
      OnAccent: onAccent;
      Link: link;
      ScrollThumb: scrollThumb;
      ScrollThumbHovered: scrollThumbHovered;
      ScrollThumbPressed: scrollThumbPressed;
      WindowEdge: windowEdge;
      WindowEdgeInactive: windowEdgeInactive;
      CloseHovered: closeHovered;
      ClosePressed: closePressed;
      ButtonNormal: {Border: buttonEdge; Fill: button; Text: text;};
      ButtonHovered: {Border: (dark ? buttonEdge : accent); Fill: buttonHot; Text: text;};
      ButtonPressed: {Border: (dark ? buttonEdge : cast Color "#005499"); Fill: buttonDown; Text: text;};
      ButtonDisabled: {Border: disabledEdge; Fill: disabledFace; Text: disabledText;};
      InputNormal: {Border: outline; Fill: page; Text: text;};
      InputHovered: {Border: (dark ? strongOutline : cast Color "#171717"); Fill: page; Text: text;};
      InputFocused: {Border: accent; Fill: page; Text: text;};
      InputDisabled: {Border: (dark ? disabledEdge : disabledFace); Fill: page; Text: disabledText;};
      CommandNormal: {HideBackground: true; Border: chrome; Fill: chrome; Text: text;};
      CommandHovered: {Border: commandDown; Fill: commandHot; Text: text;};
      CommandPressed: {Border: menuHighlight; Fill: commandDown; Text: text;};
      CommandDisabled: {HideBackground: true; Border: chrome; Fill: chrome; Text: disabledText;};
      ItemNormal: {HideBackground: true; Border: page; Fill: page; Text: text;};
      ItemHovered: {Border: (dark ? cast Color "#4C4C4C" : commandHot); Fill: (dark ? cast Color "#4C4C4C" : commandHot); Text: text;};
      ItemSelected: {Border: (dark ? cast Color "#333333" : cast Color "#99D1FF"); Fill: selected; Text: text;};
      ItemSelectedHovered: {Border: (dark ? cast Color "#333333" : cast Color "#80C3FF"); Fill: selectedHover; Text: text;};
      ItemDisabled: {HideBackground: true; Border: page; Fill: page; Text: disabledText;};
      WindowSurface: windowSurface;
      MenuHighlight: menuHighlight;
      RibbonSurface: (dark ? cast Color "#212121" : cast Color "#F5F6F7");
      RibbonBorder: (dark ? cast Color "#404040" : cast Color "#DADBDC");
      RibbonHovered: {Border: (dark ? cast Color "#646464" : cast Color "#7AB0E7"); Fill: (dark ? cast Color "#464646" : cast Color "#D5E6F7"); Text: text;};
      RibbonSelected: {Border: (dark ? cast Color "#6F6F6F" : cast Color "#62A2E4"); Fill: (dark ? cast Color "#575757" : cast Color "#C9E0F7"); Text: text;};
      RibbonPressed: {Border: (dark ? cast Color "#707070" : cast Color "#62A2E4"); Fill: (dark ? cast Color "#6B6B6B" : cast Color "#C9E0F7"); Text: text;};
      TabNormal: {Border: divider; Fill: windowSurface; Text: text;};
      TabHovered: {Border: divider; Fill: (dark ? commandHot : cast Color "#D8EAF9"); Text: text;};
    };
  }

  func CreateDefaultColorPackage() : ColorPackage
  {
    return CreateColorPackageInternal(false);
  }

  func CreateDarkColorPackage() : ColorPackage
  {
    return CreateColorPackageInternal(true);
  }

  var win10Colors : ColorPackage = CreateDefaultColorPackage();

  /*
  * Calling GuiApplication::GetApplication().RefreshThemes will reload the new baseline document.
  */
  func CreateBaselineDocument() : DocumentModel^
  {
    var document = new DocumentModel^();
    var normal = new DocumentStyle^();
    normal.styles = new DocumentStyleProperties^();
    normal.styles.color = win10Colors.Text;
    document.styles["#Default-Override"] = normal;
    var selection = new DocumentStyle^();
    selection.styles = new DocumentStyleProperties^();
    selection.styles.color = win10Colors.OnAccent;
    selection.styles.backgroundColor = win10Colors.Accent;
    document.styles["#Selection-Override"] = selection;
    var link = new DocumentStyle^();
    link.styles = new DocumentStyleProperties^();
    link.styles.color = win10Colors.Link;
    document.styles["#NormalLink-Override"] = link;
    var activeLink = new DocumentStyle^();
    activeLink.styles = new DocumentStyleProperties^();
    activeLink.styles.color = win10Colors.Text;
    document.styles["#ActiveLink-Override"] = activeLink;
    return document;
  }
}
